      zh: {"title": "厂门口的分类回收", "situation": "工业带职工和居民愿意交回收物，分拣方需要稳定供货。", "unitLabel": "年新增接收的可回收物吨数", "a": {"label": "购买厂门口的回收服务", "tradeoff": "今年开收，主要在工作日，住宅院落覆盖有限。", "beneficiaries": "企业职工"}, "b": {"label": "设置地区回收点", "tradeoff": "设备准备好后也可接收居民投放，需要运营方。", "beneficiaries": "当地居民和企业"}}
