      zh: {"title": "林边的旧垃圾场", "situation": "北部旧场地发现生活垃圾，原计划在进行，可加快额外部分。", "unitLabel": "新增完成清理并验收的百平方米地块", "a": {"label": "出资清运容易到达的部分", "tradeoff": "首批较快验收，远处继续走原计划。", "beneficiaries": "场地入口附近居民"}, "b": {"label": "整备进场道路并扩展施工范围", "tradeoff": "明年可验收更多地块，资金先用于准备。", "beneficiaries": "场地周边居民"}}
